#include "PhysicalLineObservationBuilder.h"
#include "FisheyeVirtualCameraGeometry.h"
#include <Eigen/Geometry>
#include <Eigen/LU>
#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <fstream>
#include <mutex>
#include <set>

namespace StructureSLAM { namespace {
const double kYaw[3]={-60.0,-20.0,20.0};
const double kLambda[5]={.20,.35,.50,.65,.80};
Eigen::Matrix3d K(){Eigen::Matrix3d k=Eigen::Matrix3d::Identity();k(0,0)=NativeFisheyeVirtualFx();k(1,1)=NativeFisheyeVirtualFy();k(0,2)=NativeFisheyeVirtualCx();k(1,2)=NativeFisheyeVirtualCy();return k;}
Eigen::Matrix3d Ry(double d){double a=d*M_PI/180.,c=cos(a),s=sin(a);Eigen::Matrix3d r;r<<c,0,-s,0,1,0,s,0,c;return r;}
Eigen::Matrix3d H(int i,int j){return K()*Ry(kYaw[j]-kYaw[i])*K().inverse();}
Eigen::Vector3d line(const FisheyeLineFrontend::ViewLine& x){Eigen::Vector3d p(x.virtual_line[0],x.virtual_line[1],1),q(x.virtual_line[2],x.virtual_line[3],1),l=p.cross(q);double n=l.head<2>().norm();if(n>0)l/=n;else l.setZero();return l;}
Eigen::Vector3d plane(const FisheyeLineFrontend::ViewLine& x){Eigen::Vector3d n=Ry(-kYaw[x.view_id])*K().transpose()*line(x);return n.norm()>0?n.normalized():n;}
bool inMask(const cv::Mat& m,const Eigen::Vector3d& p){if(m.empty()||fabs(p.z())<1e-12)return false;int x=(int)llround(p.x()/p.z()),y=(int)llround(p.y()/p.z());return x>=0&&y>=0&&x<m.cols&&y<m.rows&&m.at<unsigned char>(y,x)!=0;}
double angle(const Eigen::Vector3d&a,const Eigen::Vector3d&b){return acos(std::max(-1.,std::min(1.,fabs(a.normalized().dot(b.normalized())))))*180./M_PI;}
bool dominates(const PhysicalLineObservationBuilder::Evidence&a,const PhysicalLineObservationBuilder::Evidence&b){bool no_worse=a.line_angle_deg<=b.line_angle_deg&&a.line_offset_px<=b.line_offset_px&&a.sample_p90_px<=b.sample_p90_px&&a.visible_overlap>=b.visible_overlap&&a.plane_angle_deg<=b.plane_angle_deg;bool better=a.line_angle_deg<b.line_angle_deg||a.line_offset_px<b.line_offset_px||a.sample_p90_px<b.sample_p90_px||a.visible_overlap>b.visible_overlap||a.plane_angle_deg<b.plane_angle_deg;return no_worse&&better;}
struct Total{long long frames=0,v[3]={0,0,0},physical=0,single=0,two=0,three=0,amb=0,conflict=0,tested40=0,accepted40=0,e80=0,s80=0,mq=0;} total;std::mutex mu;
void flush(){const char*p=getenv("T265_PHYSICAL_BUILDER_STATS");if(!p||!*p)return;std::lock_guard<std::mutex>l(mu);std::ofstream o(p);o<<"frames,v0,v1,v2,physical,single,two,three,ambiguous,conflict,tested40,accepted40,eligible80,skipped80,mask_queries\n";o<<total.frames<<","<<total.v[0]<<","<<total.v[1]<<","<<total.v[2]<<","<<total.physical<<","<<total.single<<","<<total.two<<","<<total.three<<","<<total.amb<<","<<total.conflict<<","<<total.tested40<<","<<total.accepted40<<","<<total.e80<<","<<total.s80<<","<<total.mq<<"\n";}struct R{R(){atexit(flush);}} reg;
}

PhysicalLineObservationBuilder::Evidence PhysicalLineObservationBuilder::Compare(const FisheyeLineFrontend::ViewLine&a,const FisheyeLineFrontend::ViewLine&b,const cv::Mat&mask){Evidence e;Eigen::Matrix3d h=H(a.view_id,b.view_id);Eigen::Vector3d la=line(a),lb=line(b),lp=h.inverse().transpose()*la;if(lp.head<2>().norm()==0||lb.head<2>().norm()==0)return e;lp/=lp.head<2>().norm();e.line_angle_deg=angle(lp,lb);e.line_offset_px=fabs(lp.z()-((lp.dot(lb)<0)?-lb.z():lb.z()));std::vector<double>d;int visible=0;for(double t:kLambda){Eigen::Vector3d p((1-t)*a.virtual_line[0]+t*a.virtual_line[2],(1-t)*a.virtual_line[1]+t*a.virtual_line[3],1),q=h*p;++e.mask_queries;if(inMask(mask,q)){++visible;double x=q.x()/q.z(),y=q.y()/q.z();d.push_back(fabs(lb.dot(Eigen::Vector3d(x,y,1))));}}e.valid_samples=(int)d.size();e.common_visible=visible>0;e.visible_overlap=visible/5.0;if(!d.empty()){sort(d.begin(),d.end());e.sample_median_px=d[d.size()/2];e.sample_p90_px=d[(size_t)floor(.9*(d.size()-1))];}else e.sample_median_px=e.sample_p90_px=1e30;e.plane_angle_deg=angle(plane(a),plane(b));e.valid=true;return e;}

std::vector<PhysicalLineObservation> PhysicalLineObservationBuilder::Build(const FisheyeLineFrontend::FrameResult&f,const std::vector<cv::Mat>&m,unsigned long fid,double ts,Stats*out){Stats s;if(f.lines.size()>0)s.v0=f.lines[0].size();if(f.lines.size()>1)s.v1=f.lines[1].size();if(f.lines.size()>2)s.v2=f.lines[2].size();std::vector<std::vector<int>> link(3);std::vector<std::vector<bool>> amb(3);for(int v=0;v<3;++v){size_t n=v<(int)f.lines.size()?f.lines[v].size():0;link[v].assign(n,-1);amb[v].assign(n,false);}for(int v=0;v<2;++v){if(v+1>=(int)f.lines.size())continue;std::vector<std::vector<Evidence>> ev(f.lines[v].size(),std::vector<Evidence>(f.lines[v+1].size()));for(size_t i=0;i<f.lines[v].size();++i)for(size_t j=0;j<f.lines[v+1].size();++j){ev[i][j]=Compare(f.lines[v][i],f.lines[v+1][j],m[v+1]);++s.tested40;s.mask_queries+=ev[i][j].mask_queries;}std::vector<std::set<int>> ndA(f.lines[v].size()),ndB(f.lines[v+1].size());for(size_t i=0;i<ev.size();++i)for(size_t j=0;j<ev[i].size();++j){bool dom=false;for(size_t k=0;k<ev[i].size();++k)if(dominates(ev[i][k],ev[i][j]))dom=true;if(!dom)ndA[i].insert(j);}for(size_t j=0;j<f.lines[v+1].size();++j)for(size_t i=0;i<f.lines[v].size();++i){bool dom=false;for(size_t k=0;k<f.lines[v].size();++k)if(dominates(ev[k][j],ev[i][j]))dom=true;if(!dom)ndB[j].insert(i);}for(size_t i=0;i<ndA.size();++i){if(ndA[i].size()>1)amb[v][i]=true;if(ndA[i].size()==1){int j=*ndA[i].begin();if(ndB[j].size()==1&&*ndB[j].begin()==(int)i){link[v][i]=j;++s.accepted40;}else amb[v][i]=true;}}}
if(f.lines.size()>2)for(const auto&a:f.lines[0])for(const auto&b:f.lines[2]){Evidence e=Compare(a,b,m[2]);s.mask_queries+=e.mask_queries;if(e.common_visible)++s.eligible80;else ++s.skipped80;}
	std::vector<PhysicalLineObservation> outv;std::set<std::pair<int,int>>used;size_t flat[3]={0,0,0};if(f.lines.size()>0)flat[1]=f.lines[0].size();if(f.lines.size()>1)flat[2]=flat[1]+f.lines[1].size();for(int v=0;v<3;++v)if(v<(int)f.lines.size())for(size_t i=0;i<f.lines[v].size();++i){if(used.count({v,(int)i}))continue;PhysicalLineObservation o;o.physical_frame_id=fid;o.timestamp=ts;o.physical_line_observation_id=outv.size();bool isamb=false;auto add=[&](int vv,int ii){const auto&x=f.lines[vv][ii];isamb=isamb||amb[vv][ii];PhysicalLineObservationMember z;z.view_id=vv;z.source_line_id=x.line_id;z.virtual_observation_index=flat[vv]+ii;z.homogeneous_line=line(x);z.p_start={x.virtual_line[0],x.virtual_line[1]};z.p_end={x.virtual_line[2],x.virtual_line[3]};for(double t:kLambda)z.internal_points.push_back((1-t)*z.p_start+t*z.p_end);if(vv<(int)m.size()){z.start_mask_valid=inMask(m[vv],Eigen::Vector3d(z.p_start.x,z.p_start.y,1));z.end_mask_valid=inMask(m[vv],Eigen::Vector3d(z.p_end.x,z.p_end.y,1));o.production_mask_consumed=true;}o.members.push_back(z);used.insert({vv,ii});};add(v,i);if(v<2&&link[v][i]>=0){int j=link[v][i];add(v+1,j);if(v==0&&j<(int)link[1].size()&&link[1][j]>=0)add(2,link[1][j]);}Eigen::Vector3d n=Eigen::Vector3d::Zero();for(const auto&z:o.members){Eigen::Vector3d nz=Ry(-kYaw[z.view_id])*K().transpose()*z.homogeneous_line;if(n.dot(nz)<0)nz=-nz;if(nz.norm()>0)n+=nz.normalized();}if(n.norm()>0){o.physical_plane=n.normalized();o.plane_valid=true;}o.ambiguity_state=isamb?PhysicalLineObservation::AMBIGUOUS:(o.members.size()==3?PhysicalLineObservation::THREE_VIEW:(o.members.size()==2?PhysicalLineObservation::TWO_VIEW:PhysicalLineObservation::SINGLE_VIEW));if(o.ambiguity_state==PhysicalLineObservation::SINGLE_VIEW)++s.single;else if(o.ambiguity_state==PhysicalLineObservation::TWO_VIEW)++s.two;else if(o.ambiguity_state==PhysicalLineObservation::THREE_VIEW)++s.three;else if(o.ambiguity_state==PhysicalLineObservation::AMBIGUOUS)++s.ambiguous;outv.push_back(o);}s.physical=outv.size();if(out)*out=s;return outv;}
void PhysicalLineObservationBuilder::AccumulateAndFlushAtExit(const Stats&s){std::lock_guard<std::mutex>l(mu);++total.frames;total.v[0]+=s.v0;total.v[1]+=s.v1;total.v[2]+=s.v2;total.physical+=s.physical;total.single+=s.single;total.two+=s.two;total.three+=s.three;total.amb+=s.ambiguous;total.conflict+=s.conflict;total.tested40+=s.tested40;total.accepted40+=s.accepted40;total.e80+=s.eligible80;total.s80+=s.skipped80;total.mq+=s.mask_queries;}
}
